{"implementation":"def solve(case):
    nodes = case['nodes']
    if len(nodes) <= 1:
        return {"mst_edges": [], "total_weight": 0.0}
    core_dist = case['core_distance']
    distances = case['distances']

    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        mr = max(core_dist[u], core_dist[v], d)
        edges.append((mr, u, v))

    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = {node: node for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rx < ry:
            parent[ry] = rx
        else:
            parent[rx] = ry
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    added = 0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            added += 1
            if added == n - 1:
                break
    if added != n - 1:
        raise ValueError("Graph is disconnected; cannot build a spanning tree.")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
